/// 🧾️ A tagged-variants enum carried as one single-statement field selects its variant cursor by keyword and binds exactly that statement's record.
pub struct StatementReceiving<T:DslOwnedReceivingVariants>{source:OwnedSlot<FieldValue>,record:OwnedSlot<FieldValue>,child:Option<T::Cursor>,output:OwnedSlot<T>,phase:u8,closing:bool,failed:bool}
impl<T:DslOwnedReceivingVariants>Default for StatementReceiving<T>{fn default()->Self{Self{source:Default::default(),record:Default::default(),child:None,output:Default::default(),phase:0,closing:false,failed:false}}}
impl<T:DslOwnedReceivingVariants>StatementReceiving<T>{
 fn selected(&mut self,source:&mut Option<FieldValue>,native:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress,OriginalReceivingPrimary>{
  if self.closing||self.failed{return RetainedWorkOutcome{result:Err(invariant().into()),work:0}}if self.phase==4{return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}
  let d=match self.demands(source,body){Ok(d)=>d,Err(e)=>return RetainedWorkOutcome{result:Err(e.into()),work:0}};if !funds(g,d){return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}
  if self.phase==2{if let Some(child)=self.child.as_mut(){if !child.is_ready(){return child.step(&mut self.record.value,native,body,child_grant(g))}}}
  if self.phase==3{if let Some(child)=self.child.as_mut(){let turn=child.take_into(&mut self.output.value,child_grant(g));if self.output.value.is_some(){self.phase=4}return normal(turn)}}
  if let Err(e)=native.checkpoint(){return RetainedWorkOutcome{result:Err(e.into()),work:0}}
  let result=(||{match self.phase{
   0=>{let Some(FieldValue::Statements(list))=source.as_ref()else{return Err(invalid())};let[(keyword,_)]=list.as_slice()else{return Err(invalid())};self.child=Some(T::receiving_cursor(keyword)?);*self.source.value=source.take();self.phase=1;},
   1=>{let Some(FieldValue::Statements(list))=self.source.value.as_mut()else{return Err(invariant())};let(_,record)=list.pop().ok_or_else(invariant)?;*self.record.value=Some(FieldValue::Record(record));self.phase=2;},
   2=>self.phase=3,
   _=>return Err(invariant())}Ok(receipt(d))})();
  RetainedWorkOutcome{result:result.map_err(Into::into),work:1}
 }
}
